def count_special_permutations(A: int, B: int, M: int) -> int:
    N = A * B - 1
    if N < M:
        return _count_modular(A, B, N, M)
    return _count_exact(A, B, N) % M

def _count_modular(A, B, N, M):
    num = 1
    for i in range(2, N + 1):
        num = num * i % M
    den = 1
    for i in range(B):
        L = A if i < B - 1 else A - 1
        for j in range(L):
            below = B - 1 - i if j <= A - 2 else B - 2 - i
            den = den * ((L - j - 1) + below + 1) % M
    f = num * pow(den, -1, M) % M
    R = 1
    for s in range(2, A + B - 1):
        m = min(s - 1, A + B - 1 - s, A - 1, B - 1)
        if m == 0:
            continue
        n_ = (s + 1) * (2 * s - 3) % M
        d_ = s * (2 * s - 1) % M
        inv = pow(d_, -1, M)
        for _ in range(m):
            R = R * n_ % M * inv % M
    return f * f % M * R % M

def _count_exact(A, B, N):
    fact = 1
    for i in range(2, N + 1):
        fact *= i
    den = 1
    for i in range(B):
        L = A if i < B - 1 else A - 1
        for j in range(L):
            below = (B - 1 - i) if j <= A - 2 else (B - 2 - i)
            den *= (L - j - 1) + below + 1
    f = fact // den
    R = 1
    for s in range(2, A + B - 1):
        m = min(s - 1, A + B - 1 - s, A - 1, B - 1)
        if m == 0:
            continue
        n_ = (s + 1) * (2 * s - 3)
        d_ = s * (2 * s - 1)
        inv = pow(d_, -1, 10**10)
        R *= (n_ // d_) ** m
    return f * f * R
