            if (
                0 <= nr < H
                and 0 <= nc < W
                and grid[nr][nc] == '.'
                and not visited[nr][nc]
            ):
                visited[nr][nc] = True
                dfs(nr, nc, depth + 1)
                visited[nr][nc] = False

    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                visited[r][c] = True
                dfs(r, c, 1)
                visited[r][c] = False

