from typing import List
from functools import lru_cache

def max_score(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    @lru_cache(maxsize=None)
    def dfs(row, mask):
        if row == rows:
            return 0
        max_score = 0
        for col in range(cols):
            if grid[row][col] not in mask:
                new_mask = mask | {grid[row][col]}
                score = grid[row][col] + dfs(row + 1, new_mask)
                max_score = max(max_score, score)
        return max_score

    return dfs(0, frozenset())
