def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    if n <= 1:
        return True

    # Convert bad intervals to a set of bad squares
    bad_squares = set()
    for interval in bad_intervals:
        l, r = interval
        for square in range(l, r + 1):
            bad_squares.add(square)

    # Dynamic programming array to track reachable squares
    dp = [False] * (n + 1)
    dp[1] = True  # Starting point is always reachable

    for i in range(1, n + 1):
        if dp[i]:
            for jump in range(a, b + 1):
                if i + jump <= n and (i + jump) not in bad_squares:
                    dp[i + jump] = True

    return dp[n]
