        dp = [1] * n

        for _ in range(2, k + 1):
            pref = [0] * n
            s = 0
            for i in range(n):
                s += dp[i]
                if s >= MOD:
                    s -= MOD
                pref[i] = s

            ndp = [0] * n
            for i in range(n):
                # previous chosen index p must satisfy a[i] - a[p] >= gap
                p = bisect_right(a, a[i] - gap) - 1
                if p >= 0:
                    ndp[i] = pref[p]

            dp = ndp

        return sum(dp) % MOD

    differences = sorted({
        a[j] - a[i]
        for i in range(n)
        for j in range(i + 1, n)
        if a[i] < a[j]
    })

    ans = 0
    prev = 0

    for gap in differences:
        cnt = count_at_least(gap)
        ans = (ans + (gap - prev) * cnt) % MOD
        prev = gap

    return ans
