def count_good_arrays(n: int, m: int, k: int) -> int:
    MOD = 10**9 + 7
    if k < 0 or k > n - 1:
        return 0

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j] * (m - 1) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD

    return dp[n][k] * m % MOD
