"""Solution implementation.

Count numbers in [l, r] whose digit product is divisible by their digit sum.
"""

def product_is_divisible_by_sum(n: int) -> bool:
    digits = [int(d) for d in str(n)]
    product = 1
    digit_sum = sum(digits)
    for d in digits:
        if d != 0:
            product *= d
    return product % digit_sum == 0


def count_beautiful_numbers(l: int, r: int) -> int:
    return sum(1 for n in range(l, r + 1) if product_is_divisible_by_sum(n))
